# Not seeded:
#   sd  - Sindhi is no longer a supported language.
#   mni - entries are in Bengali script, but Sarvam writes Manipuri
#         in Meetei Mayek, so pages showed two scripts.
#   sat - entries are in Devanagari, but Sarvam writes Santali in
#         Ol Chiki, so pages showed two scripts.
# Those texts are translated by Sarvam instead.
SKIPPED_LANGUAGES = {"sd", "mni", "sat"}


def seed_translations():
    db = SessionLocal()

    try:
        inserted = 0
        updated = 0

        for message_key, languages in TRANSLATIONS.items():

            for language, translated_text in languages.items():

                if language in SKIPPED_LANGUAGES:
                    continue

                existing = (
                    db.query(Translation)
                    .filter(
                        Translation.message_key == message_key,
                        Translation.language == language,
                    )
                    .first()
                )

                if existing:
                    existing.translated_text = translated_text
                    updated += 1

                else:
                    translation = Translation(
                        message_key=message_key,
                        language=language,
                        translated_text=translated_text,
                    )

                    db.add(translation)
                    inserted += 1

        db.commit()

        print("=" * 70)
        print("FocusGuard AI Landing Translation Seed")
        print("=" * 70)
        print(f"Inserted translations : {inserted}")
        print(f"Updated translations  : {updated}")
        print(f"Translation keys      : {len(TRANSLATIONS)}")
        print("=" * 70)
        print("Translations seeded successfully.")
        print("=" * 70)

    except Exception as error:
        db.rollback()

        print("=" * 70)
        print("Translation seed failed.")
        print("=" * 70)
        print(error)
        print("=" * 70)

        raise

    finally:
        db.close()


if __name__ == "__main__":
    seed_translations()